  @doc "Number of POI/CSA pairs seeded."
  def count, do: length(@pois)

  @doc """
  Seeds all POI and CSA places and pairs each POI 1:1 with its CSA via a
  PlaceRef (POI -> CSA, role `:interconnects`). The SQ traverses CSA -> POI
  through this ref via Ash.

  Per-record and resilient: a record that fails (e.g. a constraint) is logged
  and skipped so the rest load. The `:build` actions upsert by id; the ref
  step checks for an existing pairing first, so re-running is idempotent.
  """
  def seed do
    require Logger

    Enum.each(@pois, fn {ref, name, point} ->
      try do
        Nbn.build_poi!(%{id: ref, name: name, location: point})
      rescue
        e -> Logger.error("Exception seeding POI #{ref}: #{inspect(e)}")
      end
    end)

    Enum.each(@csas, fn {ref, name, poly} ->
      try do
        Nbn.build_csa!(%{id: csa_id(ref), name: name, bounds: poly})
      rescue
        e -> Logger.error("Exception seeding CSA #{ref}: #{inspect(e)}")
      end
    end)

    Enum.each(@pois, fn {ref, _name, _point} ->
      try do
        # Idempotent pairing. The :build actions upsert by id, but
        # create_place_ref! does NOT upsert — so guard it. We check the
        # relationship directly off the CSA (load place_refs -> source_place)
        # rather than via the filtered API: `%Ash.NotLoaded{}` would mean we
        # failed to load, `[]` means no pairing yet, a matching ref means done.
        unless paired?(csa_id(ref), ref) do
          Provider.create_place_ref!(%{
            role: @interconnects,
            source: {:place, ref},
            target: csa_id(ref)
          })
        end
      rescue
        e -> Logger.error("Exception pairing POI #{ref} -> CSA: #{inspect(e)}")
      end
    end)

    :ok
  end

  defp csa_id(ref), do: "CSA-" <> ref

  # True if the CSA already has a PlaceRef from the given POI with the
  # interconnects role. Reads the relationship off the CSA via `load`
  # (place_refs -> source_place), defending against a missing CSA or an
  # unloaded relationship (treated as "not paired", so seeding proceeds).
  defp paired?(csa_id, poi_ref) do
    with {:ok, csa} <- Nbn.get_csa_by_id(csa_id),
         false <- is_nil(csa),
         {:ok, csa} <- Ash.load(csa, place_refs: [:source_place]),
         refs when is_list(refs) <- csa.place_refs do
      Enum.any?(refs, fn pr ->
        pr.role == @interconnects and pr.source_place != nil and
          pr.source_place.id == poi_ref
      end)
    else
      _ -> false
    end
  end
end
